-- 0002a_xpert_screening.sql
--
-- BeyondX admin console, Phase 2 (Xpert pipeline and screening), part A.
-- ADDITIVE ONLY: creates new tables, one private storage bucket and one new
-- permission grant. It does not read, alter or drop any existing table, so it
-- is safe to run on the shared database. NOT APPLIED YET. Show it to the
-- project owner, then run it once after 0001.
--
-- xpert_id is a plain text column with no foreign key on purpose. The Xpert
-- table belongs to the existing backend and its exact name and id type are not
-- confirmed. Migration 0002b (generated by scripts/generate-0002b.mjs once the
-- schema is known) adds the status columns on the Xpert table, the foreign
-- keys, and the guarantor backfill.

begin;

-- Status history: one row per status change, never edited or removed. ---------
create table public.status_history (
  id          bigint generated always as identity primary key,
  xpert_id    text not null,
  old_status  text,
  new_status  text not null,
  changed_by  uuid references auth.users (id),
  automatic   boolean not null default false,
  trigger     text,
  reason      text,
  changed_at  timestamptz not null default now(),
  check (old_status is null or old_status in (
    'applied','guarantor_pending','guarantor_confirmed','skill_verification',
    'provisional_active','full_active','under_review','suspended','removed',
    'inactive','blocked_closed')),
  check (new_status in (
    'applied','guarantor_pending','guarantor_confirmed','skill_verification',
    'provisional_active','full_active','under_review','suspended','removed',
    'inactive','blocked_closed'))
);
create index status_history_xpert_idx on public.status_history (xpert_id, changed_at desc);

-- Guarantors ----------------------------------------------------------------
create table public.guarantor (
  id                    uuid primary key default gen_random_uuid(),
  xpert_id              text not null,
  name                  text not null,
  contact               text not null,
  relationship          text,
  named_at              timestamptz not null default now(),
  explainer_sent_at     timestamptz,
  callback_confirmed_at timestamptz,
  callback_outcome      text check (callback_outcome in ('yes', 'no', 'no_response')),
  callback_note         text,
  retracted_at          timestamptz,
  retracted_reason      text,
  assigned_to           uuid references auth.users (id),
  assigned_at           timestamptz,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  updated_by            uuid references auth.users (id),
  change_reason         text
);
create index guarantor_xpert_idx on public.guarantor (xpert_id);
-- At most one live guarantor per Xpert. A retracted one is kept for the record.
create unique index guarantor_one_live_per_xpert on public.guarantor (xpert_id) where retracted_at is null;

-- Skill evidence ----------------------------------------------------------------
create table public.skill_evidence (
  id               uuid primary key default gen_random_uuid(),
  xpert_id         text not null,
  task_type        text not null,
  evidence_type    text not null check (evidence_type in ('submitted_evidence', 'certification')),
  link             text,
  file_path        text,
  review_outcome   text not null default 'pending' check (review_outcome in ('pending', 'pass', 'fail')),
  checklist_ticked jsonb not null default '{}'::jsonb,
  auto_fail_hits   jsonb not null default '[]'::jsonb,
  review_reason    text,
  reviewed_by      uuid references auth.users (id),
  reviewed_at      timestamptz,
  assigned_to      uuid references auth.users (id),
  assigned_at      timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  updated_by       uuid references auth.users (id),
  change_reason    text,
  check (link is not null or file_path is not null)
);
create index skill_evidence_xpert_idx on public.skill_evidence (xpert_id);
create index skill_evidence_pending_idx on public.skill_evidence (created_at) where review_outcome = 'pending';

-- Reference checks ------------------------------------------------------------
create table public.reference_check (
  id            uuid primary key default gen_random_uuid(),
  xpert_id      text not null,
  name          text not null,
  contact       text not null,
  relationship  text not null,
  outcome       text not null default 'pending'
                check (outcome in ('pending', 'confirmed', 'inconclusive', 'unreachable')),
  attempts_made integer not null default 0 check (attempts_made >= 0),
  call_log      jsonb not null default '[]'::jsonb,
  warnings      jsonb not null default '[]'::jsonb,
  called_by     uuid references auth.users (id),
  called_at     timestamptz,
  assigned_to   uuid references auth.users (id),
  assigned_at   timestamptz,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  updated_by    uuid references auth.users (id),
  change_reason text
);
create index reference_check_xpert_idx on public.reference_check (xpert_id);
create index reference_check_pending_idx on public.reference_check (created_at) where outcome = 'pending';

-- Configuration for rules the business has not fully decided. ----------------------
-- Undecided items are stored here with pending = true so they can be changed
-- from the Settings screen without a deploy. Values are JSON.
create table public.console_config (
  key           text primary key,
  value         jsonb not null,
  pending       boolean not null default false,
  note          text,
  updated_at    timestamptz not null default now(),
  updated_by    uuid references auth.users (id),
  change_reason text
);

insert into public.console_config (key, value, pending, note) values
  ('screening.guarantorDeadlineDays',       '14'::jsonb,   false, 'Decided: two weeks.'),
  ('screening.skillVerificationNudgeDays',  '14'::jsonb,   false, 'Decided: a nudge after two weeks, never an automatic status change.'),
  ('screening.referenceUnreachableAttempts','3'::jsonb,    true,  'Pending: the brief says two to three unreachable attempts. Set to 3 until decided.'),
  ('screening.cleanJobsForFullActive',      '1'::jsonb,    true,  'Pending: the brief says one to two completed jobs. Set to 1 until decided.'),
  ('screening.reverificationGapDays',       'null'::jsonb, true,  'Pending: how long a gap before an Xpert must reverify, and what that covers.'),
  ('screening.underReviewKeepsAccess',      'true'::jsonb, true,  'Pending: whether an Xpert under review can still take jobs. Set to yes until decided.'),
  ('screening.evidenceChecklists',          '{}'::jsonb,   true,  'Pending: the real checklist and automatic fail conditions per task type. Until set, a starter checklist is shown.'),
  ('screening.referenceScript',             '[]'::jsonb,   true,  'Pending: the reference call script. Until set, a starter script is shown.')
on conflict (key) do nothing;

-- Private bucket for uploaded evidence. Files are reached only through short
-- lived signed links created by the API (service role). No storage policies are
-- added, so nothing is readable from a browser session directly.
insert into storage.buckets (id, name, public)
values ('xpert-evidence', 'xpert-evidence', false)
on conflict (id) do nothing;

-- New permission: logging an Xpert going inactive or returning. -----------------
insert into public.role_permission (role, permission) values
  ('ops_reviewer',   'xperts.status.voluntary'),
  ('decision_maker', 'xperts.status.voluntary'),
  ('super_admin',    'xperts.status.voluntary')
on conflict (role, permission) do nothing;

-- Triggers (same conventions as 0001) ---------------------------------------
create trigger guarantor_touch          before update on public.guarantor        for each row execute function public.touch_updated_at();
create trigger skill_evidence_touch     before update on public.skill_evidence   for each row execute function public.touch_updated_at();
create trigger reference_check_touch    before update on public.reference_check  for each row execute function public.touch_updated_at();
create trigger console_config_touch     before update on public.console_config   for each row execute function public.touch_updated_at();

create trigger guarantor_audit       after insert or update on public.guarantor       for each row execute function public.audit_row_change('id');
create trigger skill_evidence_audit  after insert or update on public.skill_evidence  for each row execute function public.audit_row_change('id');
create trigger reference_check_audit after insert or update on public.reference_check for each row execute function public.audit_row_change('id');
create trigger console_config_audit  after insert or update on public.console_config  for each row execute function public.audit_row_change('key');

create trigger guarantor_no_delete       before delete on public.guarantor        for each row execute function public.block_hard_delete();
create trigger skill_evidence_no_delete  before delete on public.skill_evidence   for each row execute function public.block_hard_delete();
create trigger reference_check_no_delete before delete on public.reference_check  for each row execute function public.block_hard_delete();
create trigger console_config_no_delete  before delete on public.console_config   for each row execute function public.block_hard_delete();

-- status_history is itself the record of changes, so it is append only.
create or replace function public.status_history_immutable() returns trigger
language plpgsql as $$
begin
  raise exception 'status_history is append only';
end $$;
create trigger status_history_no_change before update or delete on public.status_history
  for each row execute function public.status_history_immutable();
create trigger status_history_no_truncate before truncate on public.status_history
  for each statement execute function public.status_history_immutable();

-- Row level security: read only for the right permission, no browser writes. ---
alter table public.status_history  enable row level security;
alter table public.guarantor       enable row level security;
alter table public.skill_evidence  enable row level security;
alter table public.reference_check enable row level security;
alter table public.console_config  enable row level security;

create policy status_history_read  on public.status_history  for select to authenticated using (public.has_permission('xperts.read'));
create policy guarantor_read       on public.guarantor        for select to authenticated using (public.has_permission('guarantors.review') or public.has_permission('xperts.read'));
create policy skill_evidence_read  on public.skill_evidence   for select to authenticated using (public.has_permission('evidence.review') or public.has_permission('xperts.read'));
create policy reference_check_read on public.reference_check  for select to authenticated using (public.has_permission('references.review') or public.has_permission('xperts.read'));
create policy console_config_read  on public.console_config   for select to authenticated using (public.has_permission('settings.read'));

revoke all on public.status_history, public.guarantor, public.skill_evidence, public.reference_check, public.console_config from anon, authenticated;
grant select on public.status_history, public.guarantor, public.skill_evidence, public.reference_check, public.console_config to authenticated;

commit;
